package main
import("testing";"math";"encoding/json";"os";"fmt";"math/rand";"path/filepath")
func pulse_signal(period,width int,phase float64,reset bool,amplitude,dc float64,offset int)[]float64{v:=make([]float64,16384);for n:=range v{age:=n-1024-offset;active:=age>=0&&age%period<width;angle:=phase+2*math.Pi*65984*float64(n)/(1<<20);if reset&&age>=0{angle=phase+2*math.Pi*65984*float64(age%period)/(1<<20)};env:=0.;if active{env=amplitude};v[n]=math.Round(dc+env*math.Sin(angle))};return v}
func TestIndependentEnergyQualification(t *testing.T){type observation struct{Period int `json:"true_period"`;Width int `json:"pulse_width"`;Phase float64 `json:"carrier_phase"`;Reset bool `json:"reset_carrier_each_pulse"`;Amplitude float64 `json:"amplitude"`;DC float64 `json:"dc"`;Offset int `json:"pulse_grid_offset"`;Result cadence_result `json:"result"`};rows:=[]observation{};resolved,unresolved:=0,0;maxerror:=0.;for _,period:=range[]int{256,512,1024}{for _,width:=range[]int{4,16,64,128}{for _,phase:=range[]float64{0,.7,2.2}{for _,reset:=range[]bool{false,true}{if !reset&&width==4{continue};for _,amp:=range[]float64{64,1024,8170}{for _,dc:=range[]float64{-8,0,10}{for _,offset:=range[]int{0,17}{v:=pulse_signal(period,width,phase,reset,amp,dc,offset);r:=score_energy(v[2048:]);if r.State=="finite_repeated_energy_cadence"{resolved++;error:=math.Abs(r.Period-float64(period));if error>maxerror{maxerror=error};if float64(period)<r.Bounds[0]||float64(period)>r.Bounds[1]{t.Fatalf("false cadence P%d W%d phase%g reset%v amp%g dc%g ->%+v",period,width,phase,reset,amp,dc,r)}}else{unresolved++};rows=append(rows,observation{period,width,phase,reset,amp,dc,offset,r})}}}}}}};if resolved==0{t.Fatal("no positive controls resolved")};report:=map[string]interface{}{"state":"finite_generic_native_sine_burst_qualification","controls":len(rows),"resolved":resolved,"unresolved_retained":unresolved,"maximum_resolved_period_error_samples":maxerror,"no_wrong_supported_period":true,"source":"Generic mathematical sine pulses, no chip timer/key/envelope algorithm","observations":rows};data,e:=json.MarshalIndent(report,"","  ");if e!=nil{t.Fatal(e)};write_csm_report(t,"energy-positive-qualification.json",append(data,'\n'))}
func TestEnergyControls(t *testing.T){controls:=map[string][]float64{};for _,phase:=range[]float64{0,.7,2.2}{v:=make([]float64,16384);for i:=range v{v[i]=math.Round(-8+8170*math.Sin(phase+2*math.Pi*65984*float64(i)/(1<<20)))};controls[fmt.Sprintf("held-sine-%g",phase)]=v};zero:=make([]float64,16384);stuck:=make([]float64,16384);noise:=make([]float64,16384);tiny:=make([]float64,16384);for i:=range zero{stuck[i]=1000;if i%2==0{noise[i]=-2044;tiny[i]=-1}else{noise[i]=2040}};controls["zero"]=zero;controls["stuck"]=stuck;controls["constant-level-binary-noise"]=noise;controls["tiny-floor"]=tiny;for _,period:=range[]int{1,8,16,32,64}{controls[fmt.Sprintf("too-fast-P%d",period)]=pulse_signal(period,max(1,period/4),.7,true,8170,-8,0)};jitter:=make([]float64,16384);rng:=rand.New(rand.NewSource(67));at:=1024;for at<16384{width:=32;for n:=at;n<at+width&&n<len(jitter);n++{jitter[n]=math.Round(8170*math.Sin(2*math.Pi*65984*float64(n-at)/(1<<20)))};at+=128+128*rng.Intn(7)};controls["irregular-pulses"]=jitter;out:=map[string]cadence_result{};for name,v:=range controls{r:=score_energy(v);if r.State=="finite_repeated_energy_cadence"{t.Fatalf("negative control %s falsely accepted %+v",name,r)};out[name]=r};data,e:=json.MarshalIndent(map[string]interface{}{"state":"finite_negative_controls_reject_period","controls":out,"scope":"Held sine/silence/stuck/tinyfloor/stationarytwolevelnoise/shortperiod/irregular examples only"},"","  ");if e!=nil{t.Fatal(e)};write_csm_report(t,"energy-negative-qualification.json",append(data,'\n'))}

// Optional durable reports require a new directory; routine tests use t.TempDir.
func TestMain(m *testing.M) {
 if root:=os.Getenv("JT143_CSM_REPORT_DIR");root!="" {
  if e:=os.Mkdir(root,0755);e!=nil {fmt.Fprintln(os.Stderr,e);os.Exit(1)}
 }
 os.Exit(m.Run())
}
func write_csm_report(t *testing.T,name string,data []byte) {
 t.Helper()
 root:=os.Getenv("JT143_CSM_REPORT_DIR");if root=="" {root=t.TempDir()}
 file,e:=os.OpenFile(filepath.Join(root,name),os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if e!=nil {t.Fatal(e)}
 defer file.Close()
 _,e=file.Write(data);if e!=nil {t.Fatal(e)}
 e=file.Close();if e!=nil {t.Fatal(e)}
}
